<section class="page-hero circle-hero"><div><span class="eyebrow">SMALL SPACES / MEANINGFUL CONNECTIONS</span><h1><?= t('Find your circle') ?></h1><p><?= t('Shared interests. Thoughtful conversations. Your people.') ?></p></div><span class="page-hero-art"><?= icon('users') ?></span></section>
<div class="circle-grid"><?php $circles=$a->db->all('SELECT * FROM cy_categories WHERE is_circle=1 ORDER BY sort_order,id');foreach($circles as $circle):$joined=$me && $a->categories->member((int)$circle['id'],(int)$me['id']); ?>
<article class="circle-card panel glass" data-reveal><div class="circle-card-orbit" aria-hidden="true"><i></i><i></i><span><?= icon($circle['icon']) ?></span></div><div class="circle-card-heading"><span class="pill <?= $joined?'soft':'' ?>"><?= t($joined?'Joined':((int)$circle['join_open']?'Open to join':'Joining paused')) ?></span><small>#<?= (int)$circle['id'] ?></small></div><h2><a href="<?= e(url('circle',['id'=>$circle['id']])) ?>"><?= e($circle['name']) ?></a></h2><p><?= e($circle['description']) ?></p><div class="circle-card-footer"><strong><?= (int)$circle['join_amount']?e(price((int)$circle['join_amount'],$circle['join_currency'])):t('Free') ?></strong><span class="muted"><?= (int)$circle['join_days']?(int)$circle['join_days'].' '.t('days'):t('Permanent') ?></span><a class="icon-button" aria-label="<?= e(tr('Open circle').' '.$circle['name']) ?>" href="<?= e(url('circle',['id'=>$circle['id']])) ?>"><?= icon('arrow') ?></a></div></article>
<?php endforeach ?></div><?php if(!$circles){empty_state('No circles yet. A new community starts with a shared idea.','users');} ?>
